+ */
+class JniFlowFile : public core::WeakReference {
+ public:
+  JniFlowFile(std::shared_ptr<core::FlowFile> ref, const std::shared_ptr<JavaServicer> &servicer, jobject ff)
+      : removed(false),
+        ff_object(ff),
+        ref_(ref),
