+    std::lock_guard<std::mutex> lock(mutex_);
+    if (method_ptr_ == nullptr || size_ != methods_.size()) {
+      method_ptr_ = std::unique_ptr<JNINativeMethod>(new JNINativeMethod[methods_.size()]);
+      size_ = methods_.size();
+      int i = 0;
+      for (auto &mthd : methods_) {

