+    auto env = java_servicer_->attach();
+    jmethodID mthd = env->GetMethodID(class_ref_.getReference(), "getClass", "(Ljava/lang/String;)Ljava/lang/Class;");
+    if (mthd == nullptr) {
+      ThrowIf(env);
+    }
+
