+      CompilationOpContext opContext) {
+    super.initialize(queryState, queryPlan, ctx, opContext);
+  }
+
+  @Override
+  public int execute(DriverContext driverContext) {
+    if (driverContext.getCtx().getExplainAnalyze() == AnalyzeState.RUNNING) {
+      return 0;
+    }
+
+    try {
+      Hive db = Hive.get(conf);
+      DDLDesc ddlDesc = work.getDDLDesc();
+
+      if (DESC_TO_OPARATION.containsKey(ddlDesc.getClass())) {
+        DDLOperation<?> ddlOperation = DESC_TO_OPARATION.get(ddlDesc.getClass()).newInstance();
+        ddlOperation.init(db, conf, driverContext, ddlDesc);
+        return ddlOperation.execute();
+      } else {
+        throw new IllegalArgumentException("Unknown DDL request: " + ddlDesc.getClass());
+      }
+    } catch (Throwable e) {
+      failed(e);
+      return 1;

 Review comment:
   all ddl errors are translated to error code 1; I'm not sure if that we want that...

   * we declare some exception which could haul the errorcode; and then unpack/log it here
   * not sure about the contracts this class has - but catching throwable includes all kind of crap (like OOM) - are we really want to do that?



