+          action -> replicas.stream()
+              .anyMatch(r -> r.getDatanodeDetails().equals(action.datanode)));
+
+      updateInflightAction(container, inflightDeletion,
+          action -> replicas.stream()
+              .noneMatch(r -> r.getDatanodeDetails().equals(action.datanode)));
+
+
+      /*
+       * If the container is in QUASI_CLOSED state, check and close the
+       * container if possible.
+       */
+      if (state == LifeCycleState.QUASI_CLOSED) {
+        forceCloseContainer(container, replicas);

 Review comment:
   If we issue any force close requests, we should probably return here. Else the subsequent logic may be too hard to reason about. E.g. situations like force close with delete, force close with re-replicate. What do you think?

   Also if we issue force-close in QC state, then we have at least a quorum so re-replication is not as high priority.

