+            ptransformBuilder.putInputs(entry.getKey().getId(), id);
+            AppliedPTransform<?, ?, ?> fakeImpulse =
+                AppliedPTransform.of(
+                    String.format("%s_%s", IMPULSE_PREFIX, entry.getKey().getId()),
+                    PBegin.in(p).expand(),
+                    ImmutableMap.of(entry.getKey(), entry.getValue()),
+                    Impulse.create(),
+                    p);
