+
+TEST(ChunkedArrayBuilder, Basics) {
+  auto tg = TaskGroup::MakeSerial();
+  std::unique_ptr<ChunkedArrayBuilder> builder;
+  ASSERT_OK(MakeChunkedArrayBuilder(tg, default_memory_pool(), nullptr,
+                                    struct_({field("a", int32())}), &builder));
