+template <typename Type>
+std::shared_ptr<Array> MakeFactorArrayImpl(Rcpp::IntegerVector_ factor, const std::shared_ptr<arrow::DataType>& type) {
+  using value_type = typename arrow::TypeTraits<Type>::ArrayType::value_type;
+  auto n = factor.size();
